import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    out_lines = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            K = int(next(iterator))
            A = []
            for _ in range(N):
                A.append(int(next(iterator)))
        except StopIteration:
            break

        possible = True

        for i in range(N - 1):
            if A[i] != -1 and A[i+1] != -1:
                if A[i] == A[i+1]:
                    possible = False
                    break

        if not possible:
            out_lines.append("NO")
            continue

        out_lines.append("YES")

        for i in range(N):
            if A[i] == -1:
                prev = A[i-1] if i > 0 else None
                next_val = A[i+1] if i < N - 1 else None

                if prev is None and next_val is None:
                    A[i] = 1
                elif prev is None:
                    if next_val == 1:
                        A[i] = 2
                    else:
                        A[i] = 1
                elif next_val is None:
                    if prev == 1:
                        A[i] = 2
                    else
                        A[i] = 1
                else:
                    if prev == 1:
                        A[i] = next_val if next_val != 1 else 2
                    else:
                        A[i] = prev if prev != 1 else 2
                    if A[i] == next_val:
                        if A[i] == 1:
                            A[i] = 2
                        else:
                            A[i] = 1

        out_lines.append(" ".join(map(str, A)))

    sys.stdout.write("\n".join(out_lines) + "\n")

if __name__ == "__main__":
    solve()
